<?php require_once __DIR__.'/../includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(in_array($_POST['status']??'', ['Pending','Reviewed','Resolved','Dismissed'],true))db()->prepare('UPDATE reports SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);flash('success','Report status updated.');go('reports.php');}$q=db()->query('SELECT r.*,a.name reporter,b.name reported FROM reports r JOIN users a ON a.id=r.reporter_id JOIN users b ON b.id=r.reported_id ORDER BY r.created_at DESC');page_start('Reports',true); ?><div class="card"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Reporter / Reported</th><th>Reason</th><th>Description</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($q as $r): ?><tr><td><?= e($r['reporter']) ?><div class="small text-secondary">on <?= e($r['reported']) ?></div></td><td><?= e($r['reason']) ?></td><td><?= e($r['description']) ?></td><td><?= e(substr($r['created_at'],0,10)) ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= $r['id'] ?>"><select class="form-select form-select-sm" name="status" onchange="this.form.submit()"><?php foreach(['Pending','Reviewed','Resolved','Dismissed'] as $st): ?><option <?= $st===$r['status']?'selected':'' ?>><?= $st ?></option><?php endforeach ?></select></form></td></tr><?php endforeach ?></tbody></table></div></div><?php page_end(); ?>
